package org.sleepwell.app;
import android.app.*;import android.content.*;import android.os.*;import android.widget.*;import android.view.*;
/** Exported standard timer entry, always reviewed. No incoming request starts or replaces a timer. */
public final class TimerRequestActivity extends Activity {
 private TimerRequest request;private int seconds;private String error="",pickerKind="";private Dialog picker;private Bundle restoredPicker;private boolean handed;
 @Override public void onCreate(Bundle saved){super.onCreate(saved);RecordUi.review(this);if(Build.VERSION.SDK_INT>=33)getOnBackInvokedDispatcher().registerOnBackInvokedCallback(android.window.OnBackInvokedDispatcher.PRIORITY_DEFAULT,this::finish);if(saved==null)read(getIntent());else try{request=saved.getBoolean("valid")?new TimerRequest(saved.containsKey("seconds")?saved.getInt("seconds"):null,saved.getString("message",""),saved.getBoolean("skip")):null;seconds=saved.containsKey("selectedSeconds")?saved.getInt("selectedSeconds"):saved.getInt("minutes",0)*60;if(seconds<0||seconds>86400)throw new IllegalArgumentException();error=saved.getString("error","");restoredPicker=saved.getBundle("picker");pickerKind=saved.getString("pickerKind","duration");}catch(RuntimeException invalid){request=null;seconds=0;error="This timer draft could not be restored. Open a new request.";}render();if(restoredPicker!=null&&request!=null){Bundle savedPicker=restoredPicker;restoredPicker=null;if(pickerKind.equals("message")){chooseMessage();if(picker instanceof SleepPicker.StateDialog)picker.onRestoreInstanceState(savedPicker);}else chooseDuration(savedPicker);}}
 private void read(Intent intent){handed=false;try{request=TimerRequestInput.read(intent);seconds=request.seconds==null?0:request.seconds;error="";}catch(RuntimeException invalid){request=null;seconds=0;error=invalid.getMessage()==null?"This timer request could not be read.":invalid.getMessage();}}
 @Override protected void onNewIntent(Intent intent){super.onNewIntent(intent);if(picker!=null){picker.dismiss();picker=null;}setIntent(intent);restoredPicker=null;read(intent);render();}
 private void render(){LinearLayout body=Design.page(this,false,null,n->{});RecordUi.label(this,body);RecordUi.header(body,"Review timer request",this::finish);Design.space(body,18);if(request==null){Design.text(body,"Timer request unavailable",23,600,Design.INK);Design.text(body,error,14,500,Design.MUTED);Design.fixedAction(body,"Close",this::finish);return;}Design.text(body,request.seconds==null?"Choose a timer duration":"Requested "+TimerRequest.duration(request.seconds),24,600,Design.INK);Design.space(body,16);Design.item(body,"clock","Selected duration",seconds==0?"Not chosen":TimerRequest.duration(seconds),()->chooseDuration(null));Design.line(body);Design.item(body,"keyboard","Timer message",request.message.isEmpty()?"No message":request.message,this::chooseMessage);Design.line(body);Design.space(body,12);Design.text(body,"This opens a new exact timer draft with the selected duration and message. Review its sound and challenge, then tap Start timer. The duration begins at Start; your other alarms and timers stay saved.",14,400,Design.MUTED);Design.space(body,10);Design.text(body,request.skipRequested?"The requesting app asked to skip setup. SleepWell still requires this review and a separate Start action.":"No timer starts until you confirm it in SleepWell.",12,400,Design.MUTED);LinearLayout footer=RecordUi.footer(body);if(!error.isEmpty()){TextView issue=Design.text(footer,error,13,500,NightDialTokens.NEGATIVE);issue.setContentDescription("Timer request error");issue.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);}Button next=Design.button(footer,"Review nap settings",true,this::continueDraft);RecordUi.enabled(next,seconds>0&&!handed);Design.button(footer,"Cancel request",false,this::finish);}
 private void chooseDuration(Bundle restored){if(request==null)return;if(picker!=null)picker.dismiss();pickerKind="duration";picker=new ExactTimerPicker(this,seconds==0?1200:seconds,restored,n->{seconds=n;error="";render();});}
 private void chooseMessage(){if(request==null)return;if(picker!=null)picker.dismiss();pickerKind="message";picker=SleepPicker.name(this,request.message.isEmpty()?"Timer":request.message,n->{try{request=new TimerRequest(request.seconds,n,request.skipRequested);error="";}catch(IllegalArgumentException invalid){error=invalid.getMessage();}render();});}
 private void continueDraft(){if(handed||!hasWindowFocus()||request==null)return;try{Intent clean=TimerRequestDraft.openSeconds(this,seconds,request.message);handed=true;startActivity(clean);finish();}catch(RuntimeException unavailable){handed=false;error="The timer draft could not open. Try again or cancel this request.";render();}}
 @Override protected void onSaveInstanceState(Bundle state){super.onSaveInstanceState(state);state.putBoolean("valid",request!=null);if(request!=null){if(request.seconds!=null)state.putInt("seconds",request.seconds);state.putString("message",request.message);state.putBoolean("skip",request.skipRequested);}state.putInt("selectedSeconds",seconds);state.putString("error",error);if(picker!=null&&picker.isShowing()){state.putString("pickerKind",pickerKind);if(picker instanceof ExactTimerPicker exact)state.putBundle("picker",exact.draft());else if(picker instanceof SleepPicker.StateDialog)state.putBundle("picker",picker.onSaveInstanceState());}}
 @Override protected void onDestroy(){if(picker!=null)picker.dismiss();super.onDestroy();}
 @Override public void onWindowFocusChanged(boolean focused){super.onWindowFocusChanged(focused);if(focused)RecordUi.lightBars(this);}
}
